        <div class="toolbar"><label class="search">${k(`search`)}<input id="search" type="search" placeholder="SEARCH THE MADNESS…" autocomplete="off" aria-label="Search cans"/><kbd>/</kbd></label><div class="toolbar-right"><label class="photo-toggle"><input id="photos" type="checkbox"/><span class="switch" aria-hidden="true"></span> Photos only</label><label class="sort-label">SORT <select id="sort" aria-label="Sort cans"><option value="shelf">Archive order</option><option value="az">Name: A–Z</option><option value="za">Name: Z–A</option><option value="rating-desc">Top rated</option><option value="rating-asc">Lowest rated</option></select></label></div></div>
